function [esol,A,B,C,Q] = ddcenergysolvere(R,guess)
%solves for the steady state solution $R(e)$, which is single valued in the
%DC regime.
syms e

tau = 0.01; % diffusivity ratio
sigma = 10; % Prandtl number
epsilon = 1; % dissipation paramter
delta = 0.001; % coefficinet in length scale
W = 0; % optional constant power forcing term
g = 1; % temperature gradient, nondimensionalised to +/- 1

d = g/R; % salinity gradient
D = sqrt(e^2+delta*R^2)/R; % turbulent diffusion
esol = NaN;
% Constant Power Forcing
%define steady state energy equation
p = sigma*(-D^2*g/(D+1) + D^2*d/(D+tau)) - epsilon*e^2/D + W;
%solve SSEQ for e, using initial guess guess
temp1 = double(vpasolve(p,e,guess));

% filter value of e, replacing complex and negative values with NaN
if ~isempty(temp1)
    esol = temp1;
%     esol = esol(abs(imag(esol))<0.000000001);
%     esol = esol(esol>=0);
end
if isempty(esol)
    esol = NaN;
end

%calculate values for several instability markers based on the value of e.
%normal
