^2*sigma + 2*epsilon*g^4*tau^2 + 2*delta*epsilon*g^4 + 8*epsilon*g^4*tau + d^2*esol^2*epsilon*g^2 + d^2*g^3*sigma*tau^2 + d^2*delta*g^3*sigma - d^3*delta*g^2*sigma + d^4*esol^2*g*sigma + 4*d^2*g^3*sigma*tau - 4*d^3*g^2*sigma*tau) + 4*d^2*esol^2*epsilon*g^4*tau + d^2*esol^2*epsilon*g^4*tau^2))/d^2 + esol^2*epsilon*g^6*tau^2)^2 - (4*(d^2*esol^2 + delta*g^2)*(d*esol^2*epsilon*g^5*tau - ((d^2*esol^2 + delta*g^2)*(d^3*g^4*sigma*tau^2 - d^3*esol^2*epsilon*g^3 + 2*d*epsilon*g^5*tau + 2*d*epsilon*g^5*tau^2 - d^4*g^3*sigma*tau + d*g*(d^2*esol^2 + delta*g^2)*(tau + 1)*(- sigma*d^3 + sigma*d^2*g + 2*epsilon*g^2) - d^3*esol^2*epsilon*g^3*tau))/d^2 + d*esol^2*epsilon*g^5*tau^2)^2)/d^2);
% B = (esol^3*epsilon*g)/(d*(esol^2 + (delta*g^2)/d^2)^(3/2)) - (2*esol*epsilon*g)/(d*(esol^2 + (delta*g^2)/d^2)^(1/2)) - sigma*((2*d^2*esol)/(g*((d*(esol^2 + (delta*g^2)/d^2)^(1/2))/g + 1)) - (2*d^3*esol)/(g^2*(tau + (d*(esol^2 + (delta*g^2)/d^2)^(1/2))/g)) - (d^3*esol*(esol^2 + (delta*g^2)/d^2)^(1/2))/(g^2*((d*(esol^2 + (delta*g^2)/d^2)^(1/2))/g + 1)^2) + (d^4*esol*(esol^2 + (delta*g^2)/d^2)^(1/2))/(g^3*(tau + (d*(esol^2 + (delta*g^2)/d^2)^(1/2))/g)^2));
% C = ((((d^2*esol^2 + delta*g^2)*(d^2*esol^2*epsilon*g^5 - g*(d^2*esol^2 + delta*g^2)*(2*epsilon*g^4 - d^5*esol^2*sigma - d^3*g^2*sigma + 2*epsilon*g^4*tau^2 + 2*delta*epsilon*g^4 + 8*epsilon*g^4*tau + d^2*esol^2*epsilon*g^2 + d^2*g^3*sigma*tau^2 + d^2*delta*g^3*sigma - d^3*delta*g^2*sigma + d^4*esol^2*g*sigma + 4*d^2*g^3*sigma*tau - 4*d^3*g^2*sigma*tau) - 2*epsilon*g^7*tau^2 + 4*d^2*esol^2*epsilon*g^5*tau + d^2*esol^2*epsilon*g^5*tau^2))/d^2 + esol^2*epsilon*g^7*tau^2)*(d^8*sigma*((d^2*esol^2 + delta*g^2)/d^2)^(7/2) - 2*g^2*sigma*(d^2*esol^2 + delta*g^2)^3 - g^2*sigma*tau*(d^2*esol^2 + delta*g^2)^3 - d^7*g*sigma*((d^2*esol^2 + delta*g^2)/d^2)^(7/2) - (6*epsilon*g^3*(d^2*esol^2 + delta*g^2)^3)/d^2 + 3*esol^2*epsilon*g^3*(d^2*esol^2 + delta*g^2)^2 - 4*d^3*epsilon*g^4*((d^2*esol^2 + delta*g^2)/d^2)^(5/2) - 4*d^5*epsilon*g^2*((d^2*esol^2 + delta*g^2)/d^2)^(7/2) + d*g*sigma*(d^2*esol^2 + delta*g^2)^3 - 8*d^3*epsilon*g^4*tau*((d^2*esol^2 + delta*g^2)/d^2)^(5/2) - 2*d^5*g^3*sigma*tau*((d^2*esol^2 + delta*g^2)/d^2)^(5/2) + 2*d^6*g^2*sigma*tau*((d^2*esol^2 + delta*g^2)/d^2)^(5/2) + 2*d*g*sigma*tau*(d^2*esol^2 + delta*g^2)^3 + (2*epsilon*g^5*tau^2*(d^2*esol^2 + delta*g^2)^2)/d^2 + d^3*esol^2*epsilon*g^4*((d^2*esol^2 + delta*g^2)/d^2)^(3/2) + 2*d^5*esol^2*epsilon*g^2*((d^2*esol^2 + delta*g^2)/d^2)^(5/2) + esol^2*epsilon*g^5*tau*(d^2*esol^2 + delta*g^2) + 2*d*delta*epsilon*g^6*((d^2*esol^2 + delta*g^2)/d^2)^(3/2) - (6*epsilon*g^3*tau*(d^2*esol^2 + delta*g^2)^3)/d^2 - (6*epsilon*g^5*tau*(d^2*esol^2 + delta*g^2)^2)/d^2 + 3*esol^2*epsilon*g^3*tau*(d^2*esol^2 + delta*g^2)^2 + esol^2*epsilon*g^5*tau^2*(d^2*esol^2 + delta*g^2) + d^3*esol^2*epsilon*g^4*tau^2*((d^2*esol^2 + delta*g^2)/d^2)^(3/2) - (4*delta*epsilon*g^7*tau^2*(d^2*esol^2 + delta*g^2))/d^2 - 2*d*delta*epsilon*g^6*tau^2*((d^2*esol^2 + delta*g^2)/d^2)^(3/2) + 4*d^3*esol^2*epsilon*g^4*tau*((d^2*esol^2 + delta*g^2)/d^2)^(3/2) + (4*delta*epsilon*g^7*tau*(d^2*esol^2 + delta*g^2))/d^2) - ((d^2*esol^2 + delta*g^2)/d^2)^(1/2)*(2*d*esol^2*epsilon*g^6*tau - ((d^2*esol^2 + delta*g^2)*(2*d^3*g^5*sigma*tau^2 - 2*d^3*esol^2*epsilon*g^4 + 4*d*epsilon*g^6*tau + 4*d*epsilon*g^6*tau^2 - 2*d^4*g^4*sigma*tau - 2*d^3*esol^2*epsilon*g^4*tau + 2*d*g^2*(d^2*esol^2 + delta*g^2)*(tau + 1)*(- sigma*d^3 + sigma*d^2*g + 2*epsilon*g^2)))/d^2 + 2*d*esol^2*epsilon*g^6*tau^2)*(d^8*sigma*((d^2*esol^2 + delta*g^2)/d^2)^(7/2) - 2*g^2*sigma*(d^2*esol^2 + delta*g^2)^3 - g^2*sigma*tau*(d^2*esol^2 + delta*g^2)^3 - d^7*g*sigma*((d^2*esol^2 + delta*g^2)/d^2)^(7/2) - (6*epsilon*g^3*(d^2*esol^2 + delta*g^2)^3)/d^2 + 3*esol^2*epsilon*g^3*(d^2*esol^2 + delta*g^2)^2 - 4*d^3*epsilon*g^4*((d^2*esol^2 + delta*g^2)/d^2)^(5/2) - 4*d^5*epsilon*g^2*((d^2*esol^2 + delta*g^2)/d^2)^(7/2) + d*g*sigma*(d^2*esol^2 + delta*g^2)^3 - 8*d^3*epsilon*g^4*tau*((d^2*esol^2 + delta*g^2)/d^2)^(5/2) - 2*d^5*g^3*sigma*tau*((d^2*esol^2 + delta*g^2)/d^2)^(5/2) + 2*d^6*g^2*sigma*tau*((d^2*esol^2 + delta*g^2)/d^2)^(5/2) + 2*d*g*sigma*tau*(d^2*esol^2 + delta*g^2)^3 + (2*epsilon*g^5*tau^2*(d^2*esol^2 + delta*g^2)^2)/d^2 + d^3*esol^2*epsilon*g^4*((d^2*esol^2 + delta*g^2)/d^2)^(3/2) + 2*d^5*esol^2*epsilon*g^2*((d^2*esol^2 + delta*g^2)/d^2)^(5/2) + esol^2*epsilon*g^5*tau*(d^2*esol^2 + delta*g^2) + 2*d*delta*epsilon*g^6*((d^2*esol^2 + delta*g^2)/d^2)^(3/2) - (6*epsilon*g^3*tau*(d^2*esol^2 + delta*g^2)^3)/d^2 - (6*epsilon*g^5*tau*(d^2*esol^2 + delta*g^2)^2)/d^2 + 3*esol^2*epsilon*g^3*tau*(d^2*esol^2 + delta*g^2)^2 + esol^2*epsilon*g^5*tau^2*(d^2*esol^2 + delta*g^2) + d^3*esol^2*epsilon*g^4*tau^2*((d^2*esol^2 + delta*g^2)/d^2)^(3/2) - (4*delta*epsilon*g^7*tau^2*(d^2*esol^2 + delta*g^2))/d^2 - 2*d*delta*epsilon*g^6*tau^2*((d^2*esol^2 + delta*g^2)/d^2)^(3/2) + 4*d^3*esol^2*epsilon*g^4*tau*((d^2*esol^2 + delta*g^2)/d^2)^(3/2) + (4*delta*epsilon*g^7*tau*(d^2*esol^2 + delta*g^2))/d^2))/((((d^2*esol^2 + delta*g^2)*(d^2*esol^2*epsilon*g^5 - g*(d^2*esol^2 + delta*g^2)*(2*epsilon*g^4 - d^5*esol^2*sigma - d^3*g^2*sigma + 2*epsilon*g^4*tau^2 + 2*delta*epsilon*g^4 + 8*epsilon